import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.AnimateEntity{Animation: "animation.creeper.swelling", NextState: "default",
# StopCondition: "query.any_animation_finished", StopConditionVersion: 13,
# Controller: "controller.animation.creeper_swelling", BlendOutTime: 0.5, EntityRuntimeIDs: []uint64{7, 300}}
SWELLING = bytes.fromhex(
    "1a616e696d6174696f6e2e637265657065722e7377656c6c696e670764656661756c741c71756572792e616e795f616e696d6174696f6e"
    "5f66696e69736865640d00000025636f6e74726f6c6c65722e616e696d6174696f6e2e637265657065725f7377656c6c696e670000003f"
    "0207ac02"
)

# generated by gophertunnel b8bd735:
# packet.AnimateEntity{StopConditionVersion: -1}
EMPTY = bytes.fromhex("000000ffffffff000000000000")

GOLDENS = [
    pytest.param(
        v2225.AnimateEntityPacket(
            animation="animation.creeper.swelling",
            next_state="default",
            stop_expression="query.any_animation_finished",
            stop_expression_version=13,
            controller="controller.animation.creeper_swelling",
            blend_out_time=0.5,
            runtime_ids=[7, 300],
        ),
        SWELLING,
        id="swelling",
    ),
    pytest.param(v2225.AnimateEntityPacket(stop_expression_version=-1), EMPTY, id="empty"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_animate_entity_is_packet_158(version):
    assert version.packets[158] is version.AnimateEntityPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_animate_entity_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_animate_entity_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
